function cleanDoc(doc) {
  if (!doc || typeof doc !== 'object') return doc;
  if (Array.isArray(doc)) {
    return doc.map(cleanDoc);
  }
  const cleaned = {};
  for (const [key, value] of Object.entries(doc)) {
    if (value && typeof value === 'object') {
      if (value['$oid']) {
        cleaned[key] = value['$oid'];
      } else if (value['$date']) {
        cleaned[key] = new Date(value['$date']);
      } else {
        cleaned[key] = cleanDoc(value);
      }
    } else {
      cleaned[key] = value;
    }
  }
  return cleaned;
}

async function run() {
  try {
    console.log("Connecting to MONGO_URI:", process.env.MONGO_URI);
    await mongoose.connect(process.env.MONGO_URI);
    console.log("Connected to MongoDB!");

    // Clear existing documents to reload fresh
    await User.deleteMany({});
    await Service.deleteMany({});
    await Review.deleteMany({});
    await Booking.deleteMany({});
    await VendorRequest.deleteMany({});
    console.log("Existing tables cleared.");

    // Insert cleaned documents
    await User.insertMany(cleanDoc(usersRaw));
    await Service.insertMany(cleanDoc(servicesRaw));
    await Review.insertMany(cleanDoc(reviewsRaw));
    await Booking.insertMany(cleanDoc(bookingsRaw));
    await VendorRequest.insertMany(cleanDoc(vendorRequestsRaw));

    console.log("Successfully imported all test data to the global database!");
  } catch (err) {
    console.error("Import failed:", err);
  } finally {
    await mongoose.disconnect();
    console.log("Disconnected from MongoDB.");
  }
}

run();
